on conflict (id) do update
  set first_name = coalesce(excluded.first_name, people.first_name),
      last_name = coalesce(excluded.last_name, people.last_name),
      nickname = coalesce(excluded.nickname, people.nickname),
      email = coalesce(excluded.email, people.email),
      phone = coalesce(excluded.phone, people.phone),
      street_address = coalesce(excluded.street_address, people.street_address),
      city = coalesce(excluded.city, people.city),
      state = coalesce(excluded.state, people.state),
      zip_code = coalesce(excluded.zip_code, people.zip_code),
      country = coalesce(excluded.country, people.country),
      hometown = coalesce(excluded.hometown, people.hometown),
      high_school = coalesce(excluded.high_school, people.high_school),
      college = coalesce(excluded.college, people.college),
      grad_school = coalesce(excluded.grad_school, people.grad_school),
      occupation = coalesce(excluded.occupation, people.occupation),
      spouse_name = coalesce(excluded.spouse_name, people.spouse_name),
      expected_graduation_year = coalesce(excluded.expected_graduation_year, people.expected_graduation_year),
      do_not_contact_reason = coalesce(excluded.do_not_contact_reason, people.do_not_contact_reason),
      learning_post_gesher = coalesce(excluded.learning_post_gesher, people.learning_post_gesher),
      aish_impact = coalesce(excluded.aish_impact, people.aish_impact),
      notes = coalesce(excluded.notes, people.notes),
      contact_updated_on = coalesce(excluded.contact_updated_on, people.contact_updated_on),
      do_not_contact = people.do_not_contact or excluded.do_not_contact,
      spotlight = people.spotlight or excluded.spotlight;

-- New people added in the app must not collide with the imported ids.
select setval('people_id_seq', (select max(id) from people));


-- Spellings folded in during the dedupe review, kept so search still finds a
-- man under the name whoever typed it knew him by.
on conflict do nothing;


-- 986 enrollments. The unique constraint on
-- (person_id, academic_year, level) is what makes the source sheets' duplicated
-- year entries impossible to reproduce.
on conflict (person_id, academic_year, level) do update
  set rebbe_id = coalesce(excluded.rebbe_id, enrollments.rebbe_id);


-- Parent contacts, from the 2024-25 and 2025-26 intake sheets. There is no
-- natural key here, so imported rows are replaced wholesale rather than
-- accumulating duplicates on a re-run.
delete from family_contacts where person_id in (1, 3, 7, 13, 16, 22, 27, 32, 33, 40, 50, 62, 68, 78, 81, 102, 117, 125, 141, 142, 147, 152, 155, 157, 159, 164, 190, 191, 229, 244, 245, 246, 272, 273, 278, 286, 287, 293, 303, 305, 309, 312, 318, 326, 330, 334, 336, 339, 349, 366, 367, 374, 375, 385, 386, 390, 404, 412, 418, 427, 428, 436, 441, 443, 455, 456, 458, 461, 471, 474, 478, 479, 483, 486, 504, 510, 515, 542, 555, 559, 561, 565, 569, 570, 617, 619, 623, 643, 644, 645, 646, 647, 648, 649, 650, 651, 652, 653, 654, 655, 656, 657, 658, 659, 660, 661, 662, 663, 664, 665, 666, 667, 668, 669, 670, 671, 672, 673, 674, 675, 676, 677, 678, 679, 680, 681, 683, 684, 685, 686, 687, 688, 689, 690, 691, 692, 693, 694, 695, 696, 697, 698, 699, 700, 701, 702, 703, 704, 705, 706, 707, 708, 709, 710, 711, 712, 713, 714, 715, 716, 717, 718, 719, 720, 721, 722, 723, 724, 725, 726, 727, 728, 729, 730, 731, 732, 733, 734, 735, 736, 737, 738, 739, 740, 741, 742, 743, 744, 745, 746, 747, 748, 749, 750);


-- 1646 'want to stay in touch with' answers, replacing 30
-- near-identical spreadsheet tabs. Re-running picks up whatever the rabbis have
-- added since without disturbing what is already here.
on conflict do nothing;


-- Campaign touchpoints from the 'Rebbe Contact - Alumni 2022' tab. That sheet
-- records only whether an alumnus was reached in a given push, not when, so the
-- date is a placeholder and the campaign name carries the real meaning.
delete from interactions where campaign in ('Chanukah 5783', 'Pesach 5783', 'Summer 5782');
